<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import ConfirmDialog from "@/components/ConfirmDialog.vue";
import PageHeader from "@/components/PageHeader.vue";
import StatusBadge from "@/components/StatusBadge.vue";
import { useAuthSession } from "@/composables/useAuthSession";
import { ApiError } from "@/services/http";
import { listDevices, listElevators, saveDevice, toggleDevice, type Device, type Elevator } from "@/services/infrastructure";

const items = ref<Device[]>([]); const elevators = ref<Elevator[]>([]); const search = ref(""); const estado = ref<"all" | "active" | "inactive">("all"); const page = ref(1); const pageSize = 10; const pagination = ref({ page: 1, pageSize, total: 0, totalPages: 0 }); const loading = ref(false); const saving = ref(false); const error = ref(""); const success = ref(""); const formError = ref(""); const editing = ref<Device | null>(null); const showForm = ref(false); const confirmTarget = ref<Device | null>(null); const form = ref({ codigoDispositivo: "", nombreDispositivo: "", tipoDispositivo: "", idElevador: null as number | null, direccionIp: "", macAddress: "", fabricante: "", modelo: "", versionFirmware: "" });
const auth = useAuthSession(); const canManage = computed(() => auth.user.value?.permissions.includes("DISPOSITIVOS_ADMINISTRAR") ?? false);
const message = (value: unknown) => value instanceof ApiError ? value.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listDevices(search.value, page.value, pageSize, estado.value); items.value = result.items; pagination.value = result.pagination; } catch (cause) { error.value = message(cause); } finally { loading.value = false; } }
async function loadElevators() { try { elevators.value = (await listElevators("", 1, 100)).items; } catch (cause) { error.value = message(cause); } }
function edit(item: Device | null) { if (!canManage.value) return; editing.value = item; formError.value = ""; form.value = { codigoDispositivo: item?.codigoDispositivo ?? "", nombreDispositivo: item?.nombreDispositivo ?? "", tipoDispositivo: item?.tipoDispositivo ?? "", idElevador: item?.idElevador ?? null, direccionIp: item?.direccionIp ?? "", macAddress: item?.macAddress ?? "", fabricante: item?.fabricante ?? "", modelo: item?.modelo ?? "", versionFirmware: item?.versionFirmware ?? "" }; showForm.value = true; }
async function save() { if (!canManage.value) return; formError.value = ""; saving.value = true; try { const creating = !editing.value; await saveDevice(editing.value?.idDispositivo ?? null, { ...form.value, direccionIp: form.value.direccionIp || null, macAddress: form.value.macAddress || null, fabricante: form.value.fabricante || null, modelo: form.value.modelo || null, versionFirmware: form.value.versionFirmware || null, ...(editing.value ? { usuarioActualizacion: "backoffice" } : { usuarioRegistro: "backoffice" }) }); showForm.value = false; success.value = creating ? "Dispositivo creado correctamente." : "Dispositivo actualizado correctamente."; await load(); } catch (cause) { formError.value = message(cause); } finally { saving.value = false; } }
function askToggle(item: Device) { if (canManage.value) confirmTarget.value = item; } async function toggle() { const target = confirmTarget.value; if (!target || !canManage.value) return; confirmTarget.value = null; try { await toggleDevice(target.idDispositivo, !target.estadoDispositivo); await load(); } catch (cause) { error.value = message(cause); } }
function changePage(nextPage: number) { page.value = nextPage; void load(); } watch([search, estado], () => { page.value = 1; void load(); }); onMounted(() => { void Promise.all([load(), loadElevators()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración', to: '/' }, { label: 'Accesos' }, { label: 'Dispositivos' }]" />
  <PageHeader eyebrow="Accesos / Infraestructura" title="Dispositivos" description="Administración de dispositivos asociados a elevadores." :action-label="canManage ? 'Nuevo dispositivo' : undefined" @action="edit(null)" />
  <p v-if="!canManage" class="bo-form-note">Consulta de solo lectura. Para crear, editar o cambiar el estado se requiere el permiso DISPOSITIVOS_ADMINISTRAR.</p>
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="load"><input v-model="search" placeholder="Buscar por código, nombre o tipo..." aria-label="Buscar dispositivos" /><select v-model="estado" aria-label="Filtrar por estado"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select><button class="bo-btn bo-btn-primary">Filtrar</button></form><div v-if="loading" class="bo-state">Cargando dispositivos...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay dispositivos registrados.</strong><span>Ajuste la búsqueda{{ canManage ? ' o cree un nuevo dispositivo.' : '.' }}</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Código</th><th>Dispositivo</th><th>Tipo</th><th>Elevador</th><th>Estado</th><th v-if="canManage">Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idDispositivo"><td><strong>{{ item.codigoDispositivo }}</strong></td><td>{{ item.nombreDispositivo }}</td><td>{{ item.tipoDispositivo }}</td><td>{{ item.nombreElevador ?? "Sin asignar" }}</td><td><StatusBadge :active="item.estadoDispositivo" /></td><td v-if="canManage"><div class="bo-actions"><button class="bo-action" @click="edit(item)">Editar</button><button class="bo-action" :class="{ danger: item.estadoDispositivo }" @click="askToggle(item)">{{ item.estadoDispositivo ? "Desactivar" : "Activar" }}</button></div></td></tr></tbody></table></div><footer v-if="!loading" class="bo-pagination"><span>{{ pagination.total }} registros · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1" @click="changePage(page - 1)">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages" @click="changePage(page + 1)">Siguiente</button></div></footer></section>
  <div v-if="showForm && canManage" class="bo-modal-backdrop" @click.self="showForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">{{ editing ? "Editar registro" : "Nuevo registro" }}</span><h2>{{ editing ? "Editar dispositivo" : "Crear dispositivo" }}</h2></div><button class="bo-close" type="button" @click="showForm = false">×</button></header><form class="bo-form" @submit.prevent="save"><div class="bo-form-grid"><label>Código *<input v-model="form.codigoDispositivo" maxlength="50" required /></label><label>Nombre *<input v-model="form.nombreDispositivo" maxlength="150" required /></label><label>Tipo *<input v-model="form.tipoDispositivo" maxlength="30" required /></label><label>Elevador<select v-model="form.idElevador"><option :value="null">Sin asignar</option><option v-for="elevator in elevators.filter(item => item.estadoElevador || item.idElevador === form.idElevador)" :key="elevator.idElevador" :value="elevator.idElevador">{{ elevator.codigoElevador }} · {{ elevator.nombreElevador }}</option></select></label><label>Dirección IP<input v-model="form.direccionIp" maxlength="45" /></label><label>MAC address<input v-model="form.macAddress" maxlength="50" /></label><label>Fabricante<input v-model="form.fabricante" maxlength="100" /></label><label>Modelo<input v-model="form.modelo" maxlength="100" /></label><label>Versión firmware<input v-model="form.versionFirmware" maxlength="100" /></label></div><p v-if="formError" class="bo-form-error">{{ formError }}</p><footer><button class="bo-btn" type="button" @click="showForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving ? "Guardando..." : "Guardar" }}</button></footer></form></section></div>
  <ConfirmDialog :open="Boolean(confirmTarget) && canManage" title="Cambiar estado del dispositivo" :message="confirmTarget ? `¿Desea ${confirmTarget.estadoDispositivo ? 'desactivar' : 'activar'} este dispositivo? Esta acción puede revertirse posteriormente.` : ''" :confirm-label="confirmTarget?.estadoDispositivo ? 'Desactivar' : 'Activar'" @confirm="toggle" @cancel="confirmTarget = null" />
</template>
